+    if (typeof candidate.id !== "string" || candidate.id.length === 0) {
+      fail(`Invalid input: ${label}.id must be a non-empty string.`);
+    }
+    if (ids.has(candidate.id)) fail(`Invalid input: duplicate task id '${candidate.id}'.`);
+    ids.add(candidate.id);
+
+    if (typeof candidate.duration !== "number" || !Number.isFinite(candidate.duration) || candidate.duration < 0) {
+      fail(`Invalid input: ${label}.duration must be a finite non-negative number.`);
+    }
+
+    const dependsOn = candidate.dependsOn === undefined ? [] : candidate.dependsOn;
+    if (!Array.isArray(dependsOn) || dependsOn.some((dependency) => typeof dependency !== "string")) {
+      fail(`Invalid input: ${label}.dependsOn must be an array of strings.`);
+    }
+    const uniqueDependencies = new Set(dependsOn as string[]);
+    if (uniqueDependencies.size !== dependsOn.length) {
+      fail(`Invalid input: ${label}.dependsOn must not contain duplicates.`);
+    }
+    if (uniqueDependencies.has(candidate.id)) {
+      fail(`Invalid input: ${label}.dependsOn cannot include the task itself.`);
+    }
+
+    return { id: candidate.id, duration: candidate.duration, dependsOn: [...uniqueDependencies] };
+  });
