+      start = Math.max(start, dependencySchedule.finish);
+      layer = Math.max(layer, layerById.get(dependency)! + 1);
+    }
+    const criticalDependencies = task.dependsOn.filter((dependency) => earliest[dependency].finish === start);
+    if (criticalDependencies.length > 0) {
+      path = criticalDependencies
+        .map((dependency) => [...paths.get(dependency)!, id])
+        .sort(comparePaths)[0];
+    }
+
+    const finish = start + task.duration;
+    earliest[id] = { start, finish };
+    paths.set(id, path);
+    layerById.set(id, layer);
+    if (!layers[layer]) layers[layer] = [];
+    layers[layer].push(id);
